"""Aggregate-only G-Score report and artifact audit; never launches backtests."""
from pathlib import Path
from datetime import datetime, timezone
import argparse
import hashlib
import json
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from research.studies.checkpoint_20261031.gscore_study import CASES, audit_records, decode_fragments
ROOT=Path('.local/gscore-spy-v1')
OUT=Path('.local/performance/gscore-spy-v1')


def build():
    OUT.mkdir(parents=True,exist_ok=True)
    plan=json.loads(Path('research/plans/gscore-spy-v1.json').read_text());budget=json.loads((ROOT/'budget.json').read_text());results={};audits={}
    for c in CASES:
        p=ROOT/(c+'-summary.json')
        if not p.exists():continue
        rows=json.loads(p.read_text());results[c]=rows
        try:audits[c]=audit_records(rows,c)
        except ValueError as error:audits[c]=dict(passed=False,error=str(error))
    hashes=lambda k:{a[k] for a in audits.values() if a.get('passed')}
    complete=set(results)==set(CASES)
    eligible=complete and all(a.get('passed') for a in audits.values()) and len(hashes('score_hash'))==1 and len(hashes('eligible_hash'))==1 and len({a['calendar_hash'] for a in audits.values() if 'calendar_hash' in a})==1
    decision=None
    if eligible:
        full=lambda c:next(x['metrics'] for x in results[c] if x['kind']=='full')
        a,b,e=full('gscore'),full('spy'),full('eligible')
        checks=dict(cagr_beats_spy=a['cagr']>b['cagr'],calmar_at_least_spy=a['calmar']>=b['calmar'],longest_uw_no_worse_than_spy=a['longest_uw']<=b['longest_uw'],cagr_beats_eligible=a['cagr']>e['cagr'])
        decision=dict(passed=all(checks.values()),checks=checks,drawdown_reassessment=abs(a['dd'])>.3,cagr_excess_spy=a['cagr']-b['cagr'],cagr_excess_eligible=a['cagr']-e['cagr'],status='retain-for-independent-validation-only' if all(checks.values()) else 'does-not-pass-frozen-improvement-screen')
    report=dict(study=plan['study'],generated_utc=datetime.now(timezone.utc).isoformat(),eligible=eligible,complete=complete,results=results,audits=audits,decision=decision,plan=plan,budget=budget)
    (OUT/'review.json').write_text(json.dumps(report,indent=2)+'\n')
    (OUT/'index.html').write_text(PAGE.replace('__DATA__',json.dumps(report,separators=(',',':')).replace('<','\\u003c')))
    files=[Path('research/plans/gscore-spy-v1.json'),Path('scripts/build_gscore_review.py'),Path('tests/test_gscore_study.py')]+[Path(f) for f in plan['input_hashes']]+[p for p in ROOT.rglob('*') if p.is_file()]+[OUT/'review.json',OUT/'index.html']
    files +=[p for p in [OUT/'browser-audit.json',OUT/'review-preview.png'] if p.exists()]
    manifest=dict(study=plan['study'],eligible=eligible,files=[dict(path=str(p),bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in sorted(set(files))])
    (OUT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print(json.dumps(dict(eligible=eligible,cases=list(results),decision=decision,manifest_files=len(manifest['files']))))


def audit():
    m=json.loads((OUT/'manifest.json').read_text());r=json.loads((OUT/'review.json').read_text());p=r['plan'];b=r['budget']
    for f in m['files']:
        data=Path(f['path']).read_bytes()
        if len(data)!=f['bytes'] or hashlib.sha256(data).hexdigest()!=f['sha256']:raise ValueError('Manifest drift:'+f['path'])
    if b['status']!='closed' or len(b['attempts'])>6 or any(a['status']=='reserved' for a in b['attempts']):raise ValueError('Open/excessive budget')
    if sum(max(0,sum(a['case']==c for a in b['attempts'])-1) for c in CASES)>2:raise ValueError('Retry limit')
    for f,digest in p['input_hashes'].items():
        if hashlib.sha256(Path(f).read_bytes()).hexdigest()!=digest:raise ValueError('Frozen input drift')
    old=p['negative_baseline']
    if hashlib.sha256(Path(old['manifest_path']).read_bytes()).hexdigest()!=old['manifest_sha256']:raise ValueError('CAPM negative baseline changed')
    for a in b['attempts']:
        if not datetime.fromisoformat(p['created_utc'])<=datetime.fromisoformat(a['reserved_utc'])<=datetime.fromisoformat(p['deadline_utc']):raise ValueError('Reservation outside budget')
    if not r['eligible']:raise ValueError('Financial comparison incomplete or ineligible')
    for c in CASES:
        attempts=[a for a in b['attempts'] if a['case']==c and a['status']=='completed']
        if len(attempts)!=1 or attempts[0]['source_sha256']!=p['source_hashes'][c]:raise ValueError('Actual source/attempt failed')
        rows=decode_fragments(json.loads((ROOT/(c+'-fragments.json')).read_text()),c);audit_records(rows,c)
        if rows!=r['results'][c]:raise ValueError('Packet/report mismatch')
        status=(ROOT/(c+'-visible-status.txt')).read_text();proof=json.loads((ROOT/(c+'-editor-verification.json')).read_text())
        if not proof['saved_and_reloaded_equal'] or proof['source_sha256']!=p['source_hashes'][c] or 'v2.5.0.0.18209' not in status or 'GSC_START|'+c+'|' not in status or 'Algorithm Id:('+attempts[0]['backtest_id']+') completed' not in status or 'Runtime Error' in status:raise ValueError('Hosted identity/completion failed')
    print(json.dumps(dict(passed=True,cases=4,financial_cases=3,annual_rows=30,attempts=len(b['attempts']),manifest_files=len(m['files']))))


PAGE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>G-Score · licensed candidate comparison</title><style>
:root{color-scheme:light;--ink:#203730;--line:#d4dbd0;--muted:#596c63}*{box-sizing:border-box}body{margin:0;background:#f3f1eb;color:var(--ink);font:15px/1.5 system-ui}main{max-width:1370px;margin:32px auto;padding:0 24px}h1{font-size:36px;line-height:1.15;max-width:900px;letter-spacing:-1px;margin:10px 0 20px}h2{font-size:23px;margin:30px 0 12px}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase}.note,footer{color:var(--muted)}.badge{background:#dfebdc;padding:6px 12px;border-radius:20px;display:inline-block}.warn{background:#f1ddca}.flow{background:#e4ebe1;border-left:3px solid #1b7062;padding:14px;margin:20px 0}.card,details{background:#fffdf7;padding:18px;border:1px solid var(--line);border-radius:10px;margin:12px 0}summary{cursor:pointer;font-weight:600}.scroll{overflow:auto;border:1px solid var(--line);border-radius:10px;margin:14px 0}table{background:#fffdf7;width:100%;border-collapse:collapse;font-size:13px}th,td{padding:10px;text-align:right;border-bottom:1px solid var(--line);white-space:nowrap}th:first-child,td:first-child{text-align:left}th{background:#e4eade}select{padding:8px;font:inherit;background:#fffdf7;border:1px solid var(--line);border-radius:6px}label{margin:8px 8px 8px 0;display:inline-block}.legend{display:flex;gap:20px;flex-wrap:wrap;font-size:13px}.legend span:before{content:'● ';color:var(--c)}svg{width:100%;height:300px}a{color:#196b61}footer{font-size:12px;margin:30px 0}@media(max-width:700px){h1{font-size:29px}main{padding:0 16px}}
</style><main><div class="eyebrow">Quant Trading Lab · licensed G-Score adaptation · 2016–2025</div><h1>Does fundamental stock selection add value beyond SPY and its own technology cohort?</h1><div id="status" class="badge"></div><p class="note">$300,000 simulated capital · 98% allocation targets · native IB fees + 5bp slippage · same financing · causal 2013–2015 ROA seed. Three fixed financial cases, one order-free probe. CAPM stays archived as a negative baseline.</p><div class="flow">Pinned licensed selector → free-data gate → G-Score / eligible cohort / SPY → accounting + temporal audits → fixed retain/stop screen</div><h2>Full-period results</h2><div class="scroll"><table id="full"></table></div><div id="decision" class="card"></div><h2>Year by year</h2><label for="metric">Chart metric</label><select id="metric"><option value="ret">Annual return</option><option value="dd">Annual max drawdown</option><option value="sharpe">Annual Sharpe</option><option value="annual_calmar">Annual Calmar</option><option value="uw_fraction">Time underwater</option><option value="longest_uw">Longest underwater, sessions</option><option value="longest_uw_days">Longest underwater, calendar days</option></select><div class="legend"><span style="--c:#196b61">G-Score</span><span style="--c:#697eab">Eligible cohort</span><span style="--c:#bd673b">SPY hold</span></div><div id="chart" class="card"></div><div class="scroll"><table id="annual"></table></div><h2>Execution and exposure</h2><div class="scroll"><table id="execution"></table></div><h2>Source selections and free-data gate</h2><p class="note">Cohort means source low-book/market technology names passing the required fields before the score threshold. The source counts quarterly ROA snapshots, not necessarily distinct filings. The twelve-snapshot variance bonus need not be available for every newer stock.</p><div class="scroll"><table id="cohorts"></table></div><details open><summary>Qualification and trial history</summary><div id="audit"></div><p><a href="review.json">Aggregate evidence</a> · <a href="manifest.json">Artifact manifest</a> · <a href="https://www.quantconnect.com/project/38513705">Hosted project</a></p></details><details><summary>Source, execution changes and definitions</summary><p>The original single file has an explicit Apache-2.0 grant, preserved with its header and license. Source score math, technology/full-field filters, bottom book-to-market quartile and threshold ≥5 of7 remain fixed. Ratios use market-cap-normalized R&amp;D/CapEx/SG&amp;A, with SG&amp;A a proxy for advertising. This adaptation removes ObjectStore/pickle and builds ROA state causally; annual staged target execution replaces legacy framework behavior that may create additional rebalances. No exact current hosted backtest reproduction is claimed.</p><p>G-Score and eligible cohort first invest in April2016; SPY first buys at9:45 on the first2016session. New targets sell reductions at9:35 and buy increases at9:45 after settled sells, at98% target gross. Native spreads/fills, mappings/actions and default normalization remain. Financing is6% debit ACT/360 on previous closing cash, zero credit, with native per-security interest disabled. There is no forced terminal sale. The5bp assumption is not a measured execution cost or capacity model.</p><p>Sharpe uses sample daily returns, zero risk-free return and √252. Full Calmar is calendar-day CAGR / absolute closing DD; annual Calmar uses annual total return / annual DD. Annual peaks reset; full peaks carry. Underwater calendar duration ends at the final underwater close, excluding recovery day. Open at end refers to the latest decline, not necessarily the longest.</p><p>Native lifetime-book checks are not independent cash/action/vendor-data replay. Provider original-reported and approximate filing-lag conventions are inherited, not independently validated. Historical sector exposures and risk differ; target matching does not prove equal realized exposure or independent alpha. No threshold tuning, untouched OOS, trained RL advantage, broker operation or deployment follows.</p><p><a href="https://github.com/santoshlite/StrategyLibraryQC/blob/6b406477afce2a12724dbf1031a99fbc1e1fee4d/G-Score%20Investing.py">Pinned licensed source</a> · <a href="https://www.quantconnect.com/data/morning-star-us-fundamentals">Fundamental-data conventions</a></p></details><footer>Development evidence only. CAPM's earlier costs/execution differ and are not combined into this leaderboard. Failed attempts remain preserved.</footer></main><script>
const D=__DATA__,cs=['gscore','eligible','spy'],names={gscore:'G-Score ≥5',eligible:'Eligible technology cohort',spy:'SPY hold'},colors={gscore:'#196b61',eligible:'#697eab',spy:'#bd673b'},el=id=>document.getElementById(id),pct=v=>v==null?'—':(100*v).toFixed(2)+'%',num=v=>v==null?'—':Number(v).toFixed(2),full=c=>D.results[c]?.find(r=>r.kind==='full'),annual=c=>D.results[c]?.filter(r=>r.kind==='annual').sort((a,b)=>a.year-b.year)||[];
function table(id,headers,rows){el(id).innerHTML='<thead><tr>'+headers.map(h=>`<th>${h}</th>`).join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')+'</tbody>'}
const done=cs.filter(c=>full(c)),blocked=D.budget.status==='closed'&&!D.complete;el('status').textContent=blocked?'Blocked before financial testing · retired quarterly ROA':D.eligible?'Completed · all cases qualified':'Partial / qualification incomplete';if(!D.eligible)el('status').classList.add('warn');table('full',['Case','CAGR','Total return','Max DD','Sharpe','Calmar','Underwater','Longest sessions','Calendar days','Open at end'],done.map(c=>{let m=full(c).metrics;return [names[c],pct(m.cagr),pct(m.ret),pct(m.dd),num(m.sharpe),num(m.calmar),pct(m.uw_fraction),m.longest_uw,m.longest_uw_days,m.censored?'Yes':'No']}));table('annual',['Year / case','Return','Max DD','Sharpe','Calmar','Underwater','Longest sessions','Calendar days','Open at end'],Array.from({length:10},(_,i)=>2016+i).flatMap(y=>done.map(c=>{let m=annual(c).find(r=>r.year===y)?.metrics;if(!m)return [];return [y+' · '+names[c],pct(m.ret),pct(m.dd),num(m.sharpe),num(m.annual_calmar),pct(m.uw_fraction),m.longest_uw,m.longest_uw_days,m.censored?'Yes':'No']})));table('execution',['Case','Fills','Fees USD','Financing USD','Notional USD','Mean gross','Max gross','Cash-only closes','Rebalances','Rejected','Book residual'],done.map(c=>{let a=full(c).audit;return [names[c],a.fills,num(a.fees),num(a.interest),num(a.fill_notional_usd),num(a.mean_gross)+'x',num(a.max_gross)+'x',a.cash_only_days,a.rebalances,a.rejects,num(a.native_book_residual)]}));let probe=D.results.probe?.[0];table('cohorts',['April year','Technology observations','Eligible cohort','G-score selected','12-snapshot histories','Missing minute histories'],(probe?.annual_counts||[]).map(r=>[...r,probe.coverage.find(c=>c[0]===r[0])?.[2]??'—']));
function chart(){let key=el('metric').value,vals=done.flatMap(c=>annual(c).map(r=>r.metrics[key]).filter(v=>v!=null));if(!vals.length){el('chart').textContent='Waiting for qualified financial outputs';return}let lo=Math.min(0,...vals),hi=Math.max(0,...vals),pad=Math.max((hi-lo)*.08,.01);lo-=pad;hi+=pad;let y=v=>255-(v-lo)/(hi-lo)*220,body=`<line x1="55" x2="1150" y1="${y(0)}" y2="${y(0)}" stroke="#a5aea2"/>`;for(let j=0;j<5;j++){let v=lo+(hi-lo)*j/4;body+=`<text x="48" y="${y(v)+4}" text-anchor="end" font-size="11">${['ret','dd','uw_fraction'].includes(key)?pct(v):num(v)}</text>`}done.forEach(c=>{let rows=annual(c);body+=`<polyline points="${rows.map((r,i)=>`${75+i*117},${y(r.metrics[key]??0)}`).join(' ')}" fill="none" stroke="${colors[c]}" stroke-width="2"/>`;rows.forEach((r,i)=>{let v=r.metrics[key];if(v!=null)body+=`<circle cx="${75+i*117}" cy="${y(v)}" r="4" fill="${colors[c]}"><title>${r.year} ${names[c]}: ${v}</title></circle>`})});for(let i=0;i<10;i++)body+=`<text x="${75+i*117}" y="290" text-anchor="middle" font-size="12">${2016+i}</text>`;el('chart').innerHTML=`<svg viewBox="0 0 1160 300" role="img" aria-label="Annual metric comparison">${body}</svg>`}el('metric').addEventListener('change',chart);chart();let dec=D.decision;if(dec){el('decision').innerHTML=`<p><strong>${dec.passed?'Passes the frozen development screen; independent validation still required.':'Does not pass the frozen improvement screen.'}</strong> Net CAGR excess: ${num(dec.cagr_excess_spy*100)}pp versus SPY and ${num(dec.cagr_excess_eligible*100)}pp versus its eligible cohort.</p><p>${Object.entries(dec.checks).map(([k,v])=>k.replaceAll('_',' ')+': '+(v?'pass':'fail')).join(' · ')}</p><p>30% drawdown reassessment reference: ${dec.drawdown_reassessment?'exceeded':'not exceeded in this viewed history'}. No hard loss bound or live promotion is established.</p>`}else el('decision').textContent=blocked?'No financial result exists. Current quarterly ROA is retired; the legacy feed has known reporting-date look-ahead. The separately recorded fallback retains the same aggregate task bounds.':'Final interpretation waits for qualified outputs.';el('audit').innerHTML=`<p>${Object.keys(D.results).length}/4 cases exported, including the order-free probe. Budget ${D.budget.attempts.length}/6 attempts; ${D.budget.status}. ${Object.entries(D.audits).map(([c,a])=>c+': '+(a.passed?'passed':a.error)).join(' · ')}</p><p>Raw fundamentals, prices and dense NAV remain hosted. Source/cohort hashes are compared across the probe and all financial cases.</p><div class="scroll"><table><thead><tr><th>Attempt</th><th>Case</th><th>Status</th></tr></thead><tbody>${D.budget.attempts.map(a=>`<tr><td>${a.id}</td><td>${a.case}</td><td>${a.status}</td></tr>`).join('')}</tbody></table></div>`;
</script></html>'''

if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--audit',action='store_true');args=ap.parse_args()
    audit() if args.audit else build()
